/* Integrate player motion, resolve contacts, and measure the resulting movement. */
void integrate_hero_motion(void) {
    Vec4 previous;
    Vec4 work;
    Vec4 plane;
    Hero *contact_player;
    Hero *motion_player;
    Hero *cap_player;
    float *position = (float *)&g_hero.motion.pos;
    Hero *player;
    float *delta;
    float *vertical;
    float *horizontal;
    float *extra_step;
    float *velocity;
    float *new_position;
    float *contact;
    float *external;
    float magnitude;

    qcopy(previous.f, position);
    player = (Hero *)((char *)position - 0x80);
    update_hero_attachment(player->ledge_moby, (char *)&player->motion.platform_delta, (char *)&player->motion.rot);
    /* Limit the velocity by state and mode. Inside an arm `position` moves on to the velocity; it is formed again
       below. */
    if (player->state.current == HERO_STATE_RISE_THEN_FALL_WITH_AIRBORNE_HIT_QUERY ||
        player->state.current == HERO_STATE_WRENCH_SLAM) {
        float limit;
        float *limited_velocity;

        if (!player->collision_off_frames) {
            float length;

            position = (float *)&g_hero.motion.velocity;
            length = gravity_length_xy(position);
            limit = player->capsule_radius - 0.02f;
            if (limit < length)
                vec_scale_to_length(position, position, limit);
        }
        limited_velocity = (float *)&g_hero.motion.velocity;
        magnitude = gravity_z(limited_velocity);
        limit = -*(float *)((char *)limited_velocity + 0x1FC); /* the player's gravity_limit */
        if (magnitude < limit) {
            if (limit > 0.0f)
                limit = 0.0f;
            gravity_set_z(limited_velocity, limited_velocity, limit);
        }
    } else if (player->state.control_mode == HERO_MODE_GRIND) {
        /* The same vertical clamp as in mode 22 below, written out in both places: the compiler merges the two. */
        if (!player->collision_off_frames) {
            float length;
            float limit;

            position = (float *)&g_hero.motion.velocity;
            length = vector_length_xy(position);
            limit = player->capsule_radius - 0.02f;
            if (limit < length)
                vec_set_length_xy(position, position, limit);
        }
    } else if (player->state.control_mode == 21) {
        float limit = 0.6f;

        if (!player->collision_off_frames) {
            float *limited_velocity = (float *)&g_hero.motion.velocity;

            if (FastVecLength(limited_velocity) > limit)
                vec_scale_to_length(limited_velocity, limited_velocity, limit);
        }
    } else if (player->state.control_mode == 22) {
        qcopy(work.f, position);
        work.f[2] += 0.5f;
        FastVecAdd(plane.f, work.f, (char *)&g_hero.motion.velocity);
        if (coll_line(position, plane.f, 2, 0, 0)) {
            char *hit = kalebo3_coll_hit_moby;

            if (!hit || *(short *)(hit + 0xA6) == 0x1F6 || *(short *)(hit + 0xA6) == 0x59F) {
                player = &g_hero;
                if (!player->collision_off_frames) {
                    float length;
                    float limit;

                    position = player->motion.velocity.f;
                    length = vector_length_xy(position);
                    limit = player->capsule_radius - 0.02f;
                    if (limit < length)
                        vec_set_length_xy(position, position, limit);
                }
            }
        }
    } else if (player->state.control_mode != HERO_MODE_GRAPPLE) {
        if (player->state.control_mode != HERO_MODE_GRAPPLE_SWING) {
            if (!player->collision_off_frames) {
                float length;
                float limit;

                position = (float *)&g_hero.motion.velocity;
                length = FastVecLength(position);
                limit = player->capsule_radius - 0.02f;
                if (limit < length)
                    vec_scale_to_length(position, position, limit);
            }
        }
    }
    position = (float *)&g_hero.motion.pos;
    FastVecAdd(position, position, (char *)&g_hero.motion.velocity);
    extra_step = (float *)&g_hero.move_impulse;
    FastVecAdd(position, position, extra_step);
    clear_u64_value(extra_step);
    contact_player = &g_hero;
    contact_player->wall_hit = 0;
    contact_player->coll_hit_moby = 0;
    if (FastVecLength((char *)&g_hero.motion.platform_delta) <= 0.0001f) {
        resolve_hero_collisions_with_history();
        HeroL16_UpdateGroundCollision();
        FastVecSub((char *)&g_hero.motion.displacement, position, previous.f);
        correct_hero_ground_penetration();
    } else {
        HeroL16_UpdateGroundCollision();
    }
    delta = (float *)&g_hero.motion.resolved_velocity;
    new_position = (float *)&g_hero.motion.pos;
    horizontal = (float *)&g_hero.motion.resolved_velocity_xy;
    FastVecSub(delta, new_position, previous.f);
    qcopy(horizontal, delta);
    vertical = (float *)&g_hero.motion.resolved_velocity_z;
    qcopy(vertical, delta);
    velocity = (float *)&g_hero.motion.velocity;
    vec_scale_to_length(delta, delta, 1.0f);
    magnitude = FastVecDot(delta, velocity);
    if (magnitude < 0.0f)
        magnitude = 0.0f;
    vec_scale_to_length(delta, velocity, magnitude);
    qcopy(work.f, velocity);
    gravity_flatten(work.f, work.f);
    gravity_flatten(horizontal, horizontal);
    vec_scale_to_length(horizontal, horizontal, 1.0f);
    magnitude = FastVecDot(horizontal, work.f);
    if (magnitude < 0.0f)
        magnitude = 0.0f;
    vec_scale_to_length(horizontal, work.f, magnitude);
    qcopy(plane.f, velocity);
    set_gravity_relative_vector_length_xy(plane.f, plane.f, 0.0f);
    set_gravity_relative_vector_length_xy(vertical, vertical, 0.0f);
    vec_scale_to_length(vertical, vertical, 1.0f);
    magnitude = FastVecDot(vertical, plane.f);
    if (magnitude < 0.0f)
        magnitude = 0.0f;
    vec_scale_to_length(vertical, plane.f, magnitude);
    motion_player = &g_hero;
    motion_player->motion.speed_xy = FastVecLength(delta);
    motion_player->motion.flat_speed = vector_length_xy(delta);
    work.q = *(Q *)delta;
    motion_player->motion.forward_speed = forward_component(work.f);
    if (motion_player->motion.forward_speed < 0.0f)
        motion_player->motion.forward_speed = 0.0f;
    qcopy(work.f, new_position);
    contact = (float *)&g_hero.motion.platform_delta;
    external = (float *)&g_hero.motion.displacement;
    if (FastVecLength(contact) > 0.0001f) {
        float saved;

        FastVecAdd(new_position, new_position, contact);
        saved = motion_player->motion.platform_delta.f[3];
        clear_u64_value(contact);
        motion_player->motion.platform_delta.f[3] = saved;
        resolve_hero_collisions_with_history();
        HeroL16_UpdateGroundCollision();
        FastVecSub(external, new_position, previous.f);
        correct_hero_ground_penetration();
    }
    FastVecSub((char *)&motion_player->motion.platform_carry, new_position, work.f);
    motion_player->motion.platform_carry.f[3] = motion_player->motion.platform_delta.f[3];
    motion_player->motion.platform_delta.f[3] = 0.0f;
    FastVecSub(external, new_position, previous.f);
    motion_player->motion.move_slope = 0.0f;
    if (motion_player->motion.flat_speed > 0.004f) {
        motion_player->motion.move_slope = motion_player->motion.displacement.f[2] / motion_player->motion.flat_speed;
        if (motion_player->motion.move_slope > 0.5f)
            motion_player->motion.move_slope = 0.5f;
        else if (motion_player->motion.move_slope < -0.5f)
            motion_player->motion.move_slope = -0.5f;
    }
    cap_player = &g_hero;
    magnitude = g_frame_time * 52.0f;
    if (magnitude < cap_player->motion.speed_xy) {
        FastVecScale(cap_player->motion.displacement.f, cap_player->motion.displacement.f,
                     magnitude / cap_player->motion.speed_xy);
        cap_player->motion.speed_xy = g_frame_time * 52.0f;
    }
}
